                  <div class="BGWhiteElement">
                        <div class="RelativeElement IsolateElement OverflowHiddenElement BGGradientToBottomElement FromPurple100TwentyElement">
                              <div class="MarginXAutoElement MaxWidth7XL PaddingBottom24Element PaddingTop10Element SmallPaddingBottom32Element LargeGridElement LargeGridColumns2Element LargeGapX8Element LargePaddingX8Element LargePaddingY40Element">
