            <div id="mc7akf">
                  <div class="RelativeElement BGPurple50Element PaddingY24Element SmallPaddingY32Element">
                        <div class="AbsoluteElement InsetZeroElement FlexElement ItemsCenterElement JustifyCenterElement Opacity10Element">
                              <svg class="WidthThreeQuarterElement HeightThreeQuarterElement TextGray300Element" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
                                    <path d="M12 0C5.372 0 0 5.372 0 12c0 6.627 5.372 12 12 12s12-5.373 12-12c0-6.628-5.372-12-12-12zm0 20.8c-4.844 0-8.8-3.956-8.8-8.8S7.156 3.2 12 3.2 20.8 7.156 20.8 12 16.844 20.8 12 20.8z"></path>
